import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"60、【节】 兑下坎上","description":"周易尚氏学 - 60、【节】 兑下坎上","frontmatter":{"title":"60、【节】 兑下坎上","description":"周易尚氏学 - 60、【节】 兑下坎上"},"headers":[],"relativePath":"zh/classics/shangshi/065.md","filePath":"zh/classics/shangshi/065.md"}'),s={name:"zh/classics/shangshi/065.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_60、【节】-兑下坎上" tabindex="-1">60、【节】 兑下坎上 <a class="header-anchor" href="#_60、【节】-兑下坎上" aria-label="Permalink to “60、【节】 兑下坎上”">​</a></h1><p>坎居西方。兑又居西。合为一处。故曰节。节信也。古剖竹为符。合以取信。故说文云。节竹约也。序卦云。物不可以终离。故受之以节。节之用在合。故与离对文。又曰节而信之。是序卦即以节为符信也。凡卦名皆从卦象生。震为竹。而二至五正反震。两竹相合。则信成矣。而坎为信也。苦节向无通诂。虞翻命三变成离。火炎上作苦。以说苦节。而后儒多从之。诚以诂苦为甚为过。皆不安也。按周礼考工记。辨其苦良。史纪五帝纪。舜陶于河滨。器皆不苦窳。皆以苦为恶。节所以取信。苦窳则以持久。不能符合。故曰苦节不可贞。自先天象失传。节字失诂。于是苦节之义。遂亦失矣。又坎为破。兑毁折。按卦象节易苦窳。戒之所以慎始也。</p><p>彖曰。节亨。刚柔分而刚得中。苦节不可贞。其道穷也。说以行险。当位以节。中正以通。天地节而四时成。节以制度。不伤财。不害民。</p><p>艮为道。又止故道穷。苟子性恶篇。故善言古者必有节于今。节信也。四时往来。不差不忒。故曰天地节而四时成。艮为时为成。震卦数四。故曰四时成。度丈尺也。度有制则民有信。信则不伤财。不害民。</p><p>象曰。泽上有水。节。君子以制数度。议德行。</p><p>数度皆所以取信于民。数纪于一。协于十。长于百。大于千。衍于万。有数而度量衡以起。度十分为寸。十寸为尺。十尺为丈。而度之生由于律。律竹管也。累巨（左禾）黍九十为九寸。以为黄钟之长。用以度长短。虞书云。同律度量衡。诚以日久度量衡或差。同之以律。则不失毫厘。律者节也。人之德行。亦有定节。以取信于世。与数度同。故君子取以为法焉。</p><p>初九。不出户庭。无咎。</p><p>初应在四。艮为户庭。而二阳为阻。故不宜出。不出则无咎。象曰知通塞。言二阻寒也。</p><h3 id="象曰。不出户庭。知通塞也。" tabindex="-1">象曰。不出户庭。知通塞也。 <a class="header-anchor" href="#象曰。不出户庭。知通塞也。" aria-label="Permalink to “象曰。不出户庭。知通塞也。”">​</a></h3><p>初应在坎。坎为通。二遇敌。不能应四。故曰塞。知其塞不出户庭。以求通。故曰知通塞。吴先生曰。易以阳在前为塞。阴在前为通。初之不出。以九二在前。故曰知通塞。二则可出而不出。故有失时之凶也。</p><p>九二。不出门庭。凶。</p><p>互艮为门庭。二比重阴。阳遇阴则通。通则利往。乃竟不出。是失时也。故凶。</p><h3 id="象曰。不出门庭凶。失时极也。" tabindex="-1">象曰。不出门庭凶。失时极也。 <a class="header-anchor" href="#象曰。不出门庭凶。失时极也。" aria-label="Permalink to “象曰。不出门庭凶。失时极也。”">​</a></h3><p>艮为时。极中也。说文极栋也。栋居屋脊。当屋之中。故极为中。失时极。即失时之中也。</p><p>六三。不节若。则嗟若。无咎。</p><p>三失位无应。故曰不节。震为笑。震反为艮则嗟矣。离九三云。不鼓缶而歌。则大耋之嗟。与此象义并同也。王弼云。若辞也。语助辞也。顺二故无咎。</p><h3 id="象曰。不节之嗟。又谁咎也。" tabindex="-1">象曰。不节之嗟。又谁咎也。 <a class="header-anchor" href="#象曰。不节之嗟。又谁咎也。" aria-label="Permalink to “象曰。不节之嗟。又谁咎也。”">​</a></h3><p>言其咎在己。</p><p>六四。安节亨。</p><p>得位有应。上承九五。艮止为安。故安节亨。</p><h3 id="象曰。安节之亨。承上道也。" tabindex="-1">象曰。安节之亨。承上道也。 <a class="header-anchor" href="#象曰。安节之亨。承上道也。" aria-label="Permalink to “象曰。安节之亨。承上道也。”">​</a></h3><p>言能承上不失其道。</p><p>九五。甘节吉。往有尚。</p><p>说文。甘美也。美甘也。而坎为美脊。故坎有美象。甘节即美节也。节而美善。方可用以取信。与下苦节为对文。五当位居中。下乘重阴。正位居体。故甘节吉。爻在外为往。往得尊位。居之不疑。故曰往有尚。虞氏强命二变应五。以释往字。岂知爻在外即曰往。泰否之大小往来可证也。</p><h3 id="象曰。甘节之吉。居位中也。" tabindex="-1">象曰。甘节之吉。居位中也。 <a class="header-anchor" href="#象曰。甘节之吉。居位中也。" aria-label="Permalink to “象曰。甘节之吉。居位中也。”">​</a></h3><p>艮为居。五中位。</p><p>上六。苦节贞凶。悔亡。</p><p>甘为美则苦为恶。坎为破。故曰苦节。节为信约。窳恶则不能符合。故贞凶。得位故无悔。</p><h3 id="象曰。若节贞凶。其道穷也" tabindex="-1">象曰。若节贞凶。其道穷也 <a class="header-anchor" href="#象曰。若节贞凶。其道穷也" aria-label="Permalink to “象曰。若节贞凶。其道穷也”">​</a></h3><p>在上无应故穷。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
